{noformat}import jenkins.model.Jenkins
import hudson.model.*
import org.jenkinsci.plugins.workflow.job.WorkflowJob
import org.jenkinsci.plugins.workflow.multibranch.WorkflowMultiBranchProject
import com.cloudbees.hudson.plugins.folder.Folder

def seen = [] as Set

Jenkins.instance.getAllItems(AbstractProject).each { job ->
    def label = job.getAssignedLabelString()
    def name = job.getFullName()
    if ((label == null || label.trim() == '' || label == 'built-in') && !seen.contains(name)) {
        println "${name} is set to run on master"
        seen << name
    }
}

Jenkins.instance.getAllItems(WorkflowMultiBranchProject).each { mb ->
    def label = mb.getAssignedLabel()?.getName()
    def name = mb.getFullName()
    if ((label == null || label.trim() == '' || label == 'master') && !seen.contains(name)) {
        println "${name} is set to run on master"
        seen << name
    }
}{noformat}

{noformat}PL/merged-branch-cleanup is set to run on master
PL/old-tags-remove is set to run on master
PL/unmerged-branch-notify is set to run on master
PL/unmerged-branch-remove is set to run on master{noformat}

